package com.projecteden.cheer.controller; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.projecteden.cheer.dto.CheerResponseDTO; import com.projecteden.cheer.service.CheerService; import com.projecteden.user.domain.User; @RestController @RequestMapping("/api/cheers") public class CheerController{private final CheerService service;public CheerController(CheerService service){this.service=service;}@PostMapping("/{friendId}") public CheerResponseDTO cheer(@AuthenticationPrincipal User u,@PathVariable Long friendId){return service.cheer(u.getId(),friendId);}}
